import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { build } from "esbuild";
import prettier from "prettier";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const runtimePath = path.join(
  root,
  "packages",
  "platform-electron-main",
  "src",
  "document-preload-runtime.ts",
);
const outputPath = path.join(
  root,
  "packages",
  "platform-electron-main",
  "src",
  "document-preload-bundle.ts",
);

export async function buildDocumentPreloadBundleTemplate() {
  const result = await build({
    entryPoints: [runtimePath],
    bundle: true,
    platform: "browser",
    format: "cjs",
    target: "chrome142",
    external: ["electron"],
    alias: {
      "@rsrender/contracts": path.join(root, "packages", "contracts", "src", "index.ts"),
    },
    treeShaking: true,
    minify: false,
    legalComments: "none",
    charset: "utf8",
    write: false,
    logLevel: "silent",
  });
  if (result.outputFiles.length !== 1) throw new Error("DOCUMENT_PRELOAD_BUNDLE_OUTPUT_INVALID");
  const template = result.outputFiles[0]?.text;
  if (
    typeof template !== "string" ||
    !template.includes('Number("__RSRENDER_INITIAL_SEQUENCE_LITERAL__")') ||
    template.match(/__RSRENDER_INITIAL_SEQUENCE_LITERAL__/gu)?.length !== 1
  ) {
    throw new Error("DOCUMENT_PRELOAD_BUNDLE_PLACEHOLDER_INVALID");
  }
  return template;
}

export async function generatedDocumentPreloadBundleModule() {
  const template = await buildDocumentPreloadBundleTemplate();
  return prettier.format(
    `/** Mechanically generated by tooling/generate-document-preload-bundle.mjs. */\nexport const documentPreloadBundleTemplate = ${JSON.stringify(template)} as const;\n`,
    { parser: "typescript" },
  );
}

export async function verifyDocumentPreloadBundleModule() {
  const expected = await generatedDocumentPreloadBundleModule();
  try {
    return (await readFile(outputPath, "utf8")) === expected;
  } catch {
    return false;
  }
}

if (process.argv.includes("--write")) {
  await writeFile(outputPath, await generatedDocumentPreloadBundleModule(), "utf8");
} else if (!(await verifyDocumentPreloadBundleModule())) {
  throw new Error("DOCUMENT_PRELOAD_BUNDLE_DRIFT");
}
